CH = string.ascii_lowercase
MASK = 0
V = len(CH) + 1
N = 10
STOI = {c: i + 1 for i, c in enumerate(CH)}
TRAIN_SET, FULL = set(WORDS), set(WORDS) | set(EVAL_WORDS)
print(f"train {len(WORDS)}, eval {len(EVAL_WORDS)}, N={N}", flush=True)

class Net(nn.Module):
    def __init__(self, dim=256, heads=4, layers=8, ff=1024):
        super().__init__()
        self.tok = nn.Embedding(V, dim)
        self.pos = nn.Parameter(torch.zeros(1, N, dim))
        block = nn.TransformerEncoderLayer(dim, heads, ff, dropout=0.0,
                  activation="gelu", batch_first=True, norm_first=True)
        self.blocks = nn.TransformerEncoder(block, layers)
        self.norm = nn.LayerNorm(dim)
        self.head = nn.Linear(dim, V)

    def forward(self, x):
        h = self.tok(x) + self.pos
        return self.head(self.norm(self.blocks(h)))

@torch.no_grad()
def p_for(model, tokens):
    logits = model(tokens.unsqueeze(0))[0]
    logits[:, MASK] = float("-inf")
    return logits.softmax(-1)

def draw(p_row, T):
    if T <= 0.05:
        return int(p_row.argmax())
    q = p_row.pow(1.0 / T)
    q = q / q.sum()
    return int(torch.multinomial(q, 1))

def init_toks(pre=None):
    toks = torch.full((N,), MASK, dtype=torch.long, device=dev)
    for pos, ch_ in (pre or {}).items():
        toks[pos] = STOI[ch_]
    return toks

def word_of(toks):
    return "".join(CH[int(t) - 1] for t in toks)

def s_ancestral(model, T=1.0, pre=None):
    toks = init_toks(pre); passes = 0
    while (toks == MASK).any():
        p = p_for(model, toks); passes += 1
        masked = (toks == MASK).nonzero().squeeze(1).tolist()
        i = max(masked, key=lambda j: p[j].max().item())
        toks[i] = draw(p[i], T)
    return toks, passes, 0

def s_k2(model, T=1.0, pre=None):
    toks = init_toks(pre); passes = 0
    while (toks == MASK).any():
        p = p_for(model, toks); passes += 1
        masked = (toks == MASK).nonzero().squeeze(1).tolist()
        ranked = sorted(masked, key=lambda j: p[j].max().item(), reverse=True)
        for i in ranked[:2]:
            if toks[i] == MASK:
                toks[i] = draw(p[i], T)
    return toks, passes, 0

def s_k3(model, T=1.0, pre=None):
    toks = init_toks(pre); passes = 0
    while (toks == MASK).any():
        p = p_for(model, toks); passes += 1
        masked = (toks == MASK).nonzero().squeeze(1).tolist()
        ranked = sorted(masked, key=lambda j: p[j].max().item(), reverse=True)
        for i in ranked[:3]:
            if toks[i] == MASK:
                toks[i] = draw(p[i], T)
    return toks, passes, 0

def s_threshold(model, thr=0.9, T=1.0, pre=None):
    toks = init_toks(pre); passes = 0
    while (toks == MASK).any():
        p = p_for(model, toks); passes += 1
        masked = (toks == MASK).nonzero().squeeze(1).tolist()
        conf = {j: p[j].max().item() for j in masked}
        sure = [j for j in masked if conf[j] >= thr] or [max(conf, key=conf.get)]
        for j in sure:
            toks[j] = draw(p[j], T)
    return toks, passes, 0

def s_revision(model, T=0.7, tau=0.15, max_steps=60, max_rev=3, pre=None):
    toks = init_toks(pre); passes = 0; revs = [0] * N
    sacred = set((pre or {}).keys())
    for _ in range(max_steps):
        p = p_for(model, toks); passes += 1
        committed = [j for j in range(N) if toks[j] != MASK]
        weak = [j for j in committed
                if j not in sacred
                and p[j, int(toks[j])].item() < tau and revs[j] < max_rev]
        if weak:
            for j in weak:
                toks[j] = MASK; revs[j] += 1
            continue
        masked = [j for j in range(N) if toks[j] == MASK]
        if not masked:
            break
        i = max(masked, key=lambda j: p[j].max().item())
        toks[i] = draw(p[i], T)
    return toks, passes, sum(revs)

def evaluate(model, fn, n=512, **kw):
    torch.manual_seed(0)
    outs, passes_tot, revs_tot = [], 0, 0
    for _ in range(n):
        toks, ps, rv = fn(model, **kw)
        outs.append(word_of(toks)); passes_tot += ps; revs_tot += rv
    return {"valid_train": round(sum(w in TRAIN_SET for w in outs) / n, 3),
            "valid_english": round(sum(w in FULL for w in outs) / n, 3),
            "unique": len(set(outs)),
            "passes_per_sample": round(passes_tot / n, 2),
            "revisions_per_sample": round(revs_tot / n, 2),
            "top5": Counter(outs).most_common(5)}

# ---------------- train N=10 model ----------------
data = torch.tensor([[STOI[c] for c in w] for w in WORDS], device=dev)
model = Net().to(dev)
print(f"N=10 model params {sum(p.numel() for p in model.parameters())/1e6:.2f}M", flush=True)
opt = torch.optim.AdamW(model.parameters(), lr=3e-4, weight_decay=0.01)
steps, bs = 12000, 1024
sched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=steps, eta_min=3e-5)
for step in range(1, steps + 1):
    x0 = data[torch.randint(0, len(data), (bs,), device=dev)]
    t = torch.rand(bs, 1, device=dev).clamp(min=0.05)
    mask = torch.rand(bs, N, device=dev) < t
    mask[mask.sum(1) == 0, 0] = True
    xt = torch.where(mask, torch.full_like(x0, MASK), x0)
    logits = model(xt)
    ce = F.cross_entropy(logits.view(-1, V), x0.view(-1),
                         reduction="none").view(bs, N)
    loss = ((ce * mask).sum(1) / t.squeeze(1)).mean() / N
    opt.zero_grad(); loss.backward(); opt.step(); sched.step()
    if step % 2000 == 0:
        with torch.no_grad():
            acc = ((logits.argmax(-1) == x0) & mask).float().sum() / mask.sum()
        print(f"step {step:5d}  loss {loss.item():7.4f}  masked-acc {acc:6.1%}", flush=True)
model.eval()

SAMPLERS = {
    "parallel_T1":   None,  # handled specially below
    "ancestral_T1":  (s_ancestral, {"T": 1.0}),
    "ancestral_T0.7":(s_ancestral, {"T": 0.7}),
    "ancestral_T0.5":(s_ancestral, {"T": 0.5}),
    "threshold_0.9": (s_threshold, {"thr": 0.9, "T": 1.0}),
    "k2":            (s_k2, {}),
    "k3":            (s_k3, {}),
    "revision":      (s_revision, {}),
    "revision_T0.5": (s_revision, {"T": 0.5, "tau": 0.15}),
}

def parallel_T1(model, n=512):
    torch.manual_seed(0)
    toks0 = init_toks()
    p = p_for(model, toks0)
    outs = []
    for _ in range(n):
        toks = torch.full((N,), MASK, dtype=torch.long, device=dev)
        for i in range(N):
            toks[i] = draw(p[i], 1.0)
        outs.append(word_of(toks))
    return {"valid_train": round(sum(w in TRAIN_SET for w in outs) / n, 3),
            "valid_english": round(sum(w in FULL for w in outs) / n, 3),
            "unique": len(set(outs)),
            "passes_per_sample": 1.0, "revisions_per_sample": 0.0,
            "top5": Counter(outs).most_common(5)}

results = {}
r = parallel_T1(model)
results["parallel_T1"] = r
print(f"parallel_T1        english {r['valid_english']:5.1%}  unique {r['unique']:3d}/512", flush=True)

for name, entry in SAMPLERS.items():
    if entry is None:
        continue
    fn, kw = entry
    r = evaluate(model, fn, **kw)
    results[name] = r
    print(f"{name:18s} english {r['valid_english']:5.1%}  unique {r['unique']:3d}/512"
          f"  passes {r['passes_per_sample']:6.2f}  revs {r['revisions_per_sample']:5.2f}"
          f"  top {r['top5'][:2]}", flush=True)

# greedy ancestral for the collapse reference
torch.manual_seed(0)
outs = []
for _ in range(64):
    toks, _, _ = s_ancestral(model, T=0.05)
    outs.append(word_of(toks))
results["greedy_ancestral"] = {"valid_train": round(sum(w in TRAIN_SET for w in outs)/64, 3),
    "valid_english": round(sum(w in FULL for w in outs)/64, 3),
    "unique": len(set(outs)), "passes_per_sample": 10.0,
    "revisions_per_sample": 0.0, "top5": Counter(outs).most_common(5)}
print(f"greedy_ancestral   english {results['greedy_ancestral']['valid_english']:5.1%}"
      f"  unique {results['greedy_ancestral']['unique']:3d}/64"
      f"  top {results['greedy_ancestral']['top5'][:2]}", flush=True)

uni = torch.zeros(N, V, device=dev)
for w in WORDS:
    for i, c in enumerate(w):
        uni[i, STOI[c]] += 1
uni /= uni.sum(1, keepdim=True)
with torch.no_grad():
    p0 = p_for(model, init_toks())
tv0 = (0.5 * (p0 - uni).abs().sum(1)).mean().item()
print(f"N=10 unigram TV vs analytic: {tv0:.4f}", flush=True)

json.dump({"meta": {"N": 10, "words": len(WORDS), "steps": steps,
                    "params": round(sum(p.numel() for p in model.parameters())/1e6, 2),
                    "unigram_tv": round(tv0, 4)},
           "samplers": results},
          open("results.json", "w"), indent=2)
torch.save(model.state_dict(), "modelb_n10.pt")
print("DONE", flush=True)
